-- P1b internal documentation selection comments (provisional number, Master to finalize).
-- Additive only: discussion / reply tables for the internal docs library. The
-- discussion id is the comment_<id> mark id generated by the client (dsc_+uuid);
-- marks are reconciled against these rows on every content save. RESOLVED rows
-- must carry resolver and time; replies are soft-deleted and only by their author
-- (enforced in the API). No existing table or row is touched.
CREATE TABLE "zzsh_docs"."doc_discussion" (
  "id" text PRIMARY KEY CHECK ("id" ~ '^dsc_[0-9a-f]{32}$'),
  "node_id" text NOT NULL REFERENCES "zzsh_docs"."doc_node"("id"),
  "anchor_text" text NOT NULL CHECK (char_length("anchor_text") BETWEEN 1 AND 500),
  "status" text NOT NULL DEFAULT 'OPEN' CHECK ("status" IN ('OPEN', 'RESOLVED')),
  "anchor_state" text NOT NULL DEFAULT 'PRESENT' CHECK ("anchor_state" IN ('PRESENT', 'ORPHANED')),
  "created_by_admin_id" text NOT NULL REFERENCES "zzsh_auth_admin"."user"("id"),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "resolved_by_admin_id" text REFERENCES "zzsh_auth_admin"."user"("id"),
  "resolved_at" timestamptz,
  CONSTRAINT "doc_discussion_resolved_shape" CHECK (
    ("status" = 'RESOLVED' AND "resolved_by_admin_id" IS NOT NULL AND "resolved_at" IS NOT NULL)
    OR ("status" = 'OPEN' AND "resolved_by_admin_id" IS NULL AND "resolved_at" IS NULL)
  )
);

CREATE INDEX "doc_discussion_node_status_idx" ON "zzsh_docs"."doc_discussion" ("node_id", "status");

CREATE TABLE "zzsh_docs"."doc_comment" (
  "id" text PRIMARY KEY CHECK ("id" ~ '^dcm_[0-9a-f]{32}$'),
  "discussion_id" text NOT NULL REFERENCES "zzsh_docs"."doc_discussion"("id"),
  "body" text NOT NULL CHECK (char_length("body") BETWEEN 1 AND 2000),
  "author_admin_id" text NOT NULL REFERENCES "zzsh_auth_admin"."user"("id"),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "edited_at" timestamptz,
  "deleted_at" timestamptz
);

CREATE INDEX "doc_comment_discussion_idx" ON "zzsh_docs"."doc_comment" ("discussion_id", "created_at");